questions = []
# split by number. and match groups
blocks = re.split(r'\n(?=\d+\.\s)', raw_text_1)

for block in blocks:
    if "Múltipla Escolha Complementar" in block:
        block = block.replace("Múltipla Escolha Complementar (Do 101 ao 122 - Finalizando cada item não mapeado)\n", "")
    block = block.strip()
    if not block:
        continue
    
    m = re.match(r'(\d+)\.\s(.*?)\s\((A)\)\s(.*?)\s\((B)\)\s(.*?)\s\((C)\)\s(.*?)\s\((D)\)\s(.*?)\s\((E)\)\s(.*)', block, re.DOTALL)
    if m:
        num = int(m.group(1))
        question_text = m.group(2).strip()
        opts = {
            'A': m.group(4).strip(),
            'B': m.group(6).strip(),
            'C': m.group(8).strip(),
            'D': m.group(10).strip(),
            'E': m.group(12).strip(),
        }
        
        correct_letter = correct_answers.get(num, 'A')
        correct_text = opts[correct_letter]
        
        q_obj = {
            "question": question_text,
            "options": list(opts.values()),
            "answer": correct_text,
            "explanation": f"A alternativa correta é a letra {correct_letter}. {correct_text}"
        }
        questions.append(q_obj)

